package com.shazwan.idash3;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.graphics.*;import java.util.*;
public class PrayerJourneyChecks extends Instrumentation {
 LauncherActivity a;int n,oldMode;android.content.SharedPreferences prefs;Map<String,?> before;
 void check(boolean b,String why){if(!b)throw new AssertionError(why);n++;}
 void ui(Runnable r){Throwable[] e={null};runOnMainSync(()->{try{r.run();}catch(Throwable t){e[0]=t;}});waitForIdleSync();if(e[0]!=null)throw new AssertionError(e[0]);}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle out=new Bundle();int code=Activity.RESULT_CANCELED;try{
 prefs=getTargetContext().getSharedPreferences("idash",0);before=new HashMap<>(prefs.getAll());oldMode=GlassPerf.mode();prefs.edit().putString("jakim_zone","SGR02").putBoolean("jakim",true).putBoolean("motion",false).apply();
 a=(LauncherActivity)startActivitySync(new Intent(getTargetContext(),LauncherActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));java.util.concurrent.CountDownLatch wait=new java.util.concurrent.CountDownLatch(2);a.worker.execute(()->a.main.post(wait::countDown));a.networkWorker.execute(()->a.main.post(wait::countDown));check(wait.await(45,java.util.concurrent.TimeUnit.SECONDS),"data ready");waitForIdleSync();
 ui(()->{a.page="home";a.render();});java.util.concurrent.CountDownLatch data=new java.util.concurrent.CountDownLatch(1);a.networkWorker.execute(()->a.main.post(data::countDown));check(data.await(45,java.util.concurrent.TimeUnit.SECONDS),"timetable ready");waitForIdleSync();
 ui(()->{PrayerJourneyView w=a.prayerJourney;check(w!=null&&w.getParent()!=null,"Home widget mounted");GlassPerf.setMode(a,GlassPerf.FULL);String date="2026-11-03";JakimCalendar.Day d=a.jakimDays.get(date);check(d!=null,"official data available");Calendar c=Calendar.getInstance(JakimCalendar.MY);c.clear();c.set(2026,10,3);
 for(int i=0;i<6;i++){c.set(Calendar.HOUR_OF_DAY,Integer.parseInt(d.times[i].substring(0,2)));c.set(Calendar.MINUTE,Integer.parseInt(d.times[i].substring(3,5)));w.tick(c.getTimeInMillis());check(w.phase!=null&&w.phase.current.kind==i,"boundary phase "+i);check(w.art!=null&&w.art.index==PrayerArtLayout.scene(i),"correct image artwork "+i);check(w.art.bitmap.getWidth()<=900&&w.art.bitmap.getAllocationByteCount()<2*1024*1024,"bounded decoded image "+i);w.tick(c.getTimeInMillis()+(w.phase.next.at-w.phase.current.at)/2);check(Math.abs(w.progress-.5)<.001,"real half-interval progress "+i);for(int[] size:new int[][]{{320,160},{480,260}}){w.measure(View.MeasureSpec.makeMeasureSpec(size[0],View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(size[1],View.MeasureSpec.EXACTLY));w.layout(0,0,size[0],size[1]);Bitmap image=Bitmap.createBitmap(size[0],size[1],Bitmap.Config.ARGB_8888);w.draw(new Canvas(image));check(Color.alpha(image.getPixel(5,5))==0&&Color.alpha(image.getPixel(size[0]-6,size[1]-6))==0,"transparent exterior corners "+i);check(image.getPixel(size[0]/2,size[1]/2)!=Color.TRANSPARENT,"real native draw "+i);if(size[0]==480)try(java.io.OutputStream f=new java.io.FileOutputStream(new java.io.File(a.getFilesDir(),"prayer-phase-"+i+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,f);}catch(Exception e){throw new AssertionError(e);}image.recycle();}}
 prefs.edit().putBoolean("motion",false).apply();w.tick(c.getTimeInMillis());check(!w.posted,"Smooth Transitions off stops frame callbacks");prefs.edit().putBoolean("motion",true).apply();GlassPerf.setMode(a,GlassPerf.LOW);w.tick(c.getTimeInMillis());check(!w.posted,"low mode stops frames");GlassPerf.setMode(a,GlassPerf.FULL);w.setVisibility(View.GONE);w.tick(c.getTimeInMillis());check(!w.posted,"hidden widget has no frames");w.setVisibility(View.VISIBLE);w.onWindowFocusChanged(false);check(!w.posted,"lost window focus stops frames");
 a.page="drive";a.render();check(a.driveDashboard.journey!=null,"Drive widget mounted");a.driveDashboard.pause();check(!a.driveDashboard.journey.posted,"Drive pause stops animation");a.driveDashboard.resume();a.driveDashboard.journey.tick(System.currentTimeMillis());a.page="home";a.render();check(!w.posted,"detached old widget stopped");});
 out.putString("stream","PASS: "+n+" prayer journey assertions\n");code=Activity.RESULT_OK;
 }catch(Throwable t){out.putString("stream","FAIL after "+n+": "+t+"\n");}finally{if(a!=null)ui(()->{GlassPerf.setMode(a,oldMode);a.finish();});if(prefs!=null&&before!=null)AppearanceChecks.restore(prefs,before);}finish(code,out);}
}
